      ro: ["Mineritul cuprului în Khetri datează încă din Civilizația Văii Indului.", "Complexul de Cupru Khetri (KCC) a fost inaugurat oficial în 1967.", "Este administrat de Hindustan Copper Limited, o companie de stat.", "Minele sunt situate în centura de cupru a munților Aravalli.", "Kolihan și Madhan-Kudhan sunt cele mai mari mine din acest complex.", "Facilitatea include o topitorie modernă pentru procesarea minereului brut."],
      en: ["Copper mining in Khetri has been documented since the Indus Valley period.", "The Khetri Copper Complex (KCC) was formally established in 1967.", "Hindustan Copper Limited (HCL) is the sole operator of these mines.", "The mines are located at the northeastern tip of the Aravalli Range.", "The complex produces high-purity copper cathodes and continuous cast rods.", "It includes underground mining, ore beneficiation, and smelting units."],
      es: ["Khetri es una de las minas de cobre conocidas más antiguas del mundo.", "El complejo de cobre moderno fue fundado oficialmente en 1967.", "Hindustan Copper Limited (HCL) opera las minas y la fundición.", "Las minas están situadas en el extremo noreste de las montañas Aravalli.", "Madhan-Kudhan es la mina más grande dentro del complejo de Khetri.", "El proyecto abarca minería, procesamiento, fundición y refinación."],
      pt: ["Khetri é uma das minas de cobre conhecidas mais antigas do mundo.", "O complexo de cobre moderno foi fundado oficialmente em 1967.", "A Hindustan Copper Limited (HCL) opera as minas e a fundição.", "As minas situam-se no extremo nordeste das montanhas Aravalli.", "Madhan-Kudhan é a maior mina dentro do complexo de Khetri.", "O projeto abrange mineração, processamento, fundição e refinação."],
      fr: ["Khetri est l'une des plus anciennes mines de cuivre connues au monde.", "Le complexe de cuivre moderne a été officiellement fondé en 1967.", "Hindustan Copper Limited (HCL) exploite les mines et la fonderie.", "Les mines sont situées à l'extrémité nord-est des monts Aravalli.", "Madhan-Kudhan est la plus grande mine du complexe de Khetri.", "Le projet englobe l'extraction, le traitement, la fusion et le raffinage."],
